def get_reward_subtask_one(self):
    pulling_cabinet_joint_pos = self._env.data.qpos[-(4 * 7) - 2]
    door_openness_reward = abs(pulling_cabinet_joint_pos / 0.4)
    subtask_complete = door_openness_reward > 0.95
    return (
        door_openness_reward,
        {
            "door_openness_reward": door_openness_reward,
            "subtask_complete": subtask_complete,
        },
        subtask_complete,
    )

def get_reward_subtask_two(self):
    drawer_joint_pos = self._env.data.qpos[-(4 * 7) - 5]
    door_openness_reward = abs(drawer_joint_pos / 0.45)
    subtask_complete = door_openness_reward > 0.95
    return (
        door_openness_reward,
        {
            "door_openness_reward": door_openness_reward,
            "subtask_complete": subtask_complete,
        },
        subtask_complete,
    )

def get_reward(self):
    reward_dict = {}
    next_obj_obs = self.obs_dict["obj_qp"]
    completions = []
    all_completed_so_far = True
    for i, element in enumerate(self.tasks_to_complete):
        element_idx = OBS_ELEMENT_INDICES[element]
        distance = np.linalg.norm(
            next_obj_obs[..., element_idx] - self.goal[element_idx]
        )
        complete = distance < BONUS_THRESH
        if complete and (all_completed_so_far or not self.ENFORCE_TASK_ORDER):
            completions.append(element)
        all_completed_so_far = all_completed_so_far and complete
    if self.REMOVE_TASKS_WHEN_COMPLETE:
        for element in completions:
            del self.tasks_to_complete[element]
        # [self.tasks_to_complete.remove(element) for element in completions]
    bonus = float(len(completions))

    reward_dict["success_subtasks"] = len(self.TASK_ELEMENTS) - len(
        self.tasks_to_complete
    )
    reward_dict["success"] = 0
    if len(self.tasks_to_complete) == 0:
        reward_dict["success"] = 1

    return bonus, reward_dict

def update_move_direction(self):
    prev_maze_stage = self.maze_stage

    if self.maze_stage == 0:
        self._env.named.model.geom_rgba["intersection_a"] = np.array([0, 1, 0, 1])

    dist_cp = np.linalg.norm(
        self._env.named.data.xpos["pelvis"][:2]
        - self.checkpoints[self.maze_stage][:2]
    )
    if dist_cp < 0.4:
        if self.maze_stage == 0:
            self.move_direction = np.array([1, 0, 0])
            self._env.named.model.geom_rgba["intersection_a"] = np.array(
                [0, 1, 0, 1]
            )
            self._env.named.model.geom_rgba["intersection_b"] = np.array(
                [1, 0, 0, 1]
            )
        elif self.maze_stage == 1:
            self.move_direction = np.array([0, 1, 0])
            self._env.named.model.geom_rgba["intersection_b"] = np.array(
                [0, 1, 0, 1]
            )
            self._env.named.model.geom_rgba["intersection_c"] = np.array(
                [1, 0, 0, 1]
            )
        elif self.maze_stage == 2:
            self.move_direction = np.array([1, 0, 0])
            self._env.named.model.geom_rgba["intersection_c"] = np.array(
                [0, 1, 0, 1]
            )
            self._env.named.model.geom_rgba["intersection_d"] = np.array(
                [1, 0, 0, 1]
            )
        elif self.maze_stage == 3:
            self.move_direction = np.array([0, 1, 0])
            self._env.named.model.geom_rgba["intersection_d"] = np.array(
                [0, 1, 0, 1]
            )

        self.maze_stage += 1
        self.maze_stage = min(self.maze_stage, 4)

    if prev_maze_stage < self.maze_stage:
        return self.maze_stage * 100

    return 0

def upon_table(self, package):
    return (
        self._env.named.data.xpos[package][0] < 2.35
        and self._env.named.data.xpos[package][1] < -1.35
        and self._env.named.data.xpos[package][0] > 1.65
        and self._env.named.data.xpos[package][1] > -2.05
        and self._env.named.data.xpos[package][2] > 0.5
    )
